"use strict";var countdownWrapper=document.querySelector(".countdown__wrapper"),items=document.querySelectorAll(".timer__box p"),targetInCentral=new Date(Date.UTC(2026,9,3,16,30,0));console.log(targetInCentral);var futureTime=targetInCentral.getTime(),getRemainingTime=function(){var n=(new Date).getTime(),e=futureTime-n,t=864e5,i=36e5,o=[Math.floor(e/t),Math.floor(e%t/i),Math.floor(e%i/6e4),Math.floor(e%6e4/1e3)];items.forEach((function(n,e){n.innerHTML=function(n){return n<10?"0".concat(n):n}(o[e])})),e<0&&(clearInterval(countdown),countdownWrapper.innerHTML='\n        <div class="countdown__image">\n          <img src="https://i.univbkstr.com/img/landing/graduation/motionW.png" alt="" role="presentation"\n            class="img-fluid">\n        </div>\n\n        <div class="timer__text">Go Badgers!</div>\n\n        <div class="countdown__image">\n          <img src="https://i.univbkstr.com/img/landing/graduation/motionW.png" alt="" role="presentation"\n            class="img-fluid">\n        </div>\n    ')},countdown=setInterval(getRemainingTime,1e3);getRemainingTime();